pub fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    debug_assert!(tol > 0);

    // Use i16 to avoid overflow when computing differences/absolute values.
    let diff = (a as i16) - (b as i16);
    let tol16 = tol as i16;

    // Strictly within (-tol, tol)  <=>  |diff| < tol
    diff.abs() < tol16
}

pub fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    debug_assert!(tol > 0);
    debug_assert_eq!(a.len(), b.len());
    debug_assert!(!a.is_empty());

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| is_close_i8(x, y, tol))
        .collect()
}